mapper.select:
select exists(
    select 1
    from venue
    where id = #{venueId}
      and status = 'ENABLED'
)

select exists(
    select 1
    from venue_comment
    where id = #{commentId}
)

mapper.update:
update venue_comment
set like_count = like_count + 1
where id = #{commentId}

mapper.delete:
delete from venue_comment_like
where comment_id = #{commentId}
  and user_id = #{userId}
